import{_ as r,C as a,o as e,c as n,a3 as o,b as i,w as c,a as s,E as l,a4 as u}from"./chunks/framework.CRbjHCyB.js";const f=JSON.parse('{"title":"系统架构","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"系统架构 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/catter/design/architecture"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/catter/design/architecture"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/catter/design/architecture"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/catter/design/architecture"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/catter/design/architecture"}]]},"headers":[],"relativePath":"zh/catter/design/architecture.md","filePath":"zh/catter/design/architecture.md","lastUpdated":1788608469000}'),E={name:"zh/catter/design/architecture.md"};function h(p,t,m,A,g,B){const d=a("Mermaid");return e(),n("div",null,[t[1]||(t[1]=o('<h1 id="系统架构" tabindex="-1">系统架构 <a class="header-anchor" href="#系统架构" aria-label="Permalink to &quot;系统架构&quot;">​</a></h1><p>Catter 是一个围绕 <strong>runtime</strong>（运行机制）展开的构建过程拦截与分析工具。runtime 是实际捕获进程创建行为的机制：构建系统每发起一次命令调用，runtime 负责把它变成 catter 可处理的事件，并按脚本的决策执行——原样执行、修改、跳过或中止。</p><p>脚本作者只需要理解两件事：</p><ol><li><strong>runtime 是什么、当前会话用的是哪个、它支持哪些能力</strong> —— 见下文与<a href="./runtime">运行机制</a>。</li><li><strong>四个回调组成的生命周期</strong> —— 构建级两个（<code>onStart</code> / <code>onFinish</code>），命令级两个（<code>onCommand</code> / <code>onExecution</code>）。</li></ol><h2 id="runtime-抽象" tabindex="-1">Runtime 抽象 <a class="header-anchor" href="#runtime-抽象" aria-label="Permalink to &quot;Runtime 抽象&quot;">​</a></h2><p>不同平台对&quot;拦截进程创建&quot;的可行性差异很大：hook 最全能，但在部分平台受限（例如 macOS 需要特殊开发权限）。因此 catter 把捕获机制抽象为 runtime：一个 runtime 就是一种捕获实现，并通过 <code>CatterRuntime</code> 暴露固定的一组能力描述：</p><table tabindex="0"><thead><tr><th>字段</th><th>含义</th></tr></thead><tbody><tr><td><code>type</code></td><td>runtime 类型：<code>inject</code> / <code>eslogger</code> / <code>env</code></td></tr><tr><td><code>supportActions</code></td><td>当前 runtime 支持的脚本动作（见下文 Action 一节）</td></tr><tr><td><code>supportParentId</code></td><td>捕获的命令能否报告父命令 ID（命令树、目标树等功能依赖它）</td></tr></tbody></table><p>runtime 通过 <code>-m/--mode</code> 选择，默认 <code>inject</code>。脚本在 <code>onStart</code> 收到的配置中即可查看当前 runtime 的能力，从而写出跨 runtime 兼容的脚本。</p><p>目前 <code>inject</code>（基于 hook）已实现，<code>env</code> 与 <code>eslogger</code> 在规划中。各机制的原理、平台限制与能力差异见<a href="./runtime">运行机制</a>。</p><h2 id="脚本生命周期" tabindex="-1">脚本生命周期 <a class="header-anchor" href="#脚本生命周期" aria-label="Permalink to &quot;脚本生命周期&quot;">​</a></h2><p>脚本通过四个回调与 catter 交互，构成一次完整的构建会话：</p>',11)),(e(),i(u,null,{default:c(()=>[l(d,{id:"mermaid-77",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20Script%20as%20%E7%94%A8%E6%88%B7%E8%84%9A%E6%9C%AC%0A%20%20%20%20participant%20Catter%20as%20catter%20%E5%AE%88%E6%8A%A4%E8%BF%9B%E7%A8%8B%0A%20%20%20%20participant%20Runtime%20as%20Runtime%EF%BC%88%E6%8D%95%E8%8E%B7%E6%9C%BA%E5%88%B6%EF%BC%89%0A%20%20%20%20participant%20Build%20as%20%E6%9E%84%E5%BB%BA%E7%B3%BB%E7%BB%9F%0A%0A%20%20%20%20Catter-%3E%3ECatter%3A%20%E5%8A%A0%E8%BD%BD%E8%84%9A%E6%9C%AC%0A%20%20%20%20Catter-%3E%3EScript%3A%20onStart(config)%0A%20%20%20%20Script--%3E%3ECatter%3A%20%E8%BF%94%E5%9B%9E%EF%BC%88%E5%8F%AF%E4%BF%AE%E6%94%B9%E7%9A%84%EF%BC%89config%0A%20%20%20%20Catter-%3E%3ERuntime%3A%20%E5%90%AF%E5%8A%A8%E6%9E%84%E5%BB%BA%EF%BC%88%E8%8B%A5%20config.execute%EF%BC%89%0A%20%20%20%20loop%20%E6%AF%8F%E6%9D%A1%E8%A2%AB%E6%8D%95%E8%8E%B7%E7%9A%84%E5%91%BD%E4%BB%A4%0A%20%20%20%20%20%20%20%20Runtime-%3E%3ECatter%3A%20%E5%91%BD%E4%BB%A4%E4%BA%8B%E4%BB%B6%0A%20%20%20%20%20%20%20%20Catter-%3E%3EScript%3A%20onCommand(ctx)%0A%20%20%20%20%20%20%20%20Script--%3E%3ECatter%3A%20%E5%8A%A8%E4%BD%9C%EF%BC%88skip%20%2F%20drop%20%2F%20abort%20%2F%20modify%EF%BC%89%0A%20%20%20%20%20%20%20%20Catter-%3E%3ERuntime%3A%20%E6%8C%89%E5%8A%A8%E4%BD%9C%E6%89%A7%E8%A1%8C%0A%20%20%20%20%20%20%20%20Runtime-%3E%3ECatter%3A%20%E6%89%A7%E8%A1%8C%E7%BB%93%E6%9E%9C%0A%20%20%20%20%20%20%20%20Catter-%3E%3EScript%3A%20onExecution(ctx)%0A%20%20%20%20end%0A%20%20%20%20Runtime--%3E%3ECatter%3A%20%E6%9E%84%E5%BB%BA%E8%BF%9B%E7%A8%8B%E7%BB%93%E6%9D%9F%0A%20%20%20%20Catter-%3E%3EScript%3A%20onFinish(result)%0A"})]),fallback:c(()=>[...t[0]||(t[0]=[s(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=o('<h3 id="构建级-onstart-onfinish" tabindex="-1">构建级：onStart / onFinish <a class="header-anchor" href="#构建级-onstart-onfinish" aria-label="Permalink to &quot;构建级：onStart / onFinish&quot;">​</a></h3><p><strong><code>onStart(config)</code></strong> 在构建开始前调用一次。</p><ul><li>入参 <code>CatterConfig</code> 包含：脚本路径与参数、构建系统命令及其工作目录、当前 runtime 能力、catter 选项（<code>log</code>、<code>stdioMode</code>）。</li><li>脚本可以返回修改后的 config（例如解析自己的 CLI 参数后写回）；返回 <code>void</code> 表示不修改。</li><li>设置 <code>config.execute = false</code> 可阻止 catter 启动构建（内置脚本在参数解析失败时用这种方式优雅退出）。</li></ul><p><strong><code>onFinish(result)</code></strong> 在构建进程结束后调用一次。<code>result</code> 是构建命令自身的进程结果：退出码与捕获的 stdout/stderr。内置脚本在这里落盘最终产物（例如 cdb 脚本写 <code>compile_commands.json</code>）。</p><h3 id="命令级-oncommand-onexecution" tabindex="-1">命令级：onCommand / onExecution <a class="header-anchor" href="#命令级-oncommand-onexecution" aria-label="Permalink to &quot;命令级：onCommand / onExecution&quot;">​</a></h3><p><strong><code>onCommand(ctx)</code></strong> 在每条命令被捕获后、执行前调用。</p><ul><li><code>ctx.capture</code> 是被捕获的命令：工作目录、可执行文件、完整参数、环境变量、捕获它的 runtime、父命令 ID（若 runtime 支持）。</li><li>捕获可能失败（例如 runtime 无法解析命令），此时 <code>ctx.capture</code> 是 <code>Err</code>，脚本需自行处理。</li><li>脚本通过 <code>ctx.skip()</code> / <code>ctx.drop()</code> / <code>ctx.abort()</code> / <code>ctx.modify(data)</code> / <code>ctx.setAction(action)</code> 指定动作；不指定时默认 <code>skip</code>（原样执行）。</li><li><code>ctx.ignoreDescendants()</code> 让该命令的所有子孙命令不再触发 <code>onCommand</code> / <code>onExecution</code>。想&quot;捕获这条命令但跳过它的子树&quot;时与 <code>skip</code> 搭配使用。</li></ul><p><strong><code>onExecution(ctx)</code></strong> 在每条命令执行完毕后调用。<code>ctx.result</code> 是该命令的退出码与输出。脚本可在这里做统计与失败聚合（例如 cdb 脚本的 <code>--abort-on-command-failure</code>）。</p><h2 id="action-脚本语义与执行机制的分层" tabindex="-1">Action：脚本语义与执行机制的分层 <a class="header-anchor" href="#action-脚本语义与执行机制的分层" aria-label="Permalink to &quot;Action：脚本语义与执行机制的分层&quot;">​</a></h2><p>&quot;如何处理一条命令&quot;在 catter 中分两层表达：</p><ol><li><strong>脚本层</strong>（脚本看到的）：<code>skip</code> / <code>drop</code> / <code>abort</code> / <code>modify</code>，语义化、与机制无关。</li><li><strong>协议层</strong>（proxy 执行的）：<code>DROP</code> / <code>INJECT</code> / <code>WRAP</code>，是具体的执行机制。</li></ol><p>runtime 驱动负责把脚本层动作映射到协议层动作。当前 <code>inject</code> runtime 的映射如下：</p><table tabindex="0"><thead><tr><th>脚本动作</th><th>语义</th><th>协议层映射</th></tr></thead><tbody><tr><td><code>skip</code></td><td>原样执行，catter 不干预</td><td><code>INJECT</code>（挂载 hook 执行，子孙命令仍可捕获）</td></tr><tr><td><code>drop</code></td><td>不执行，直接返回退出码 0</td><td><code>DROP</code></td></tr><tr><td><code>abort</code></td><td>中止整个构建并报错</td><td>尚未实现（见下）</td></tr><tr><td><code>modify</code></td><td>用修改后的命令替换原命令执行</td><td><code>INJECT</code>（携带修改后的命令）</td></tr></tbody></table><p>两个容易混淆的点：</p><ul><li><strong><code>skip</code> 不等于&quot;忽略整个子树&quot;</strong>。<code>skip</code> 只是让这条命令照常执行；其子孙命令仍会被捕获并触发回调。要跳过子树，需显式调用 <code>ctx.ignoreDescendants()</code>。</li><li><strong>不是所有 runtime 都支持所有动作</strong>。脚本应通过 <code>config.runtime.supportActions</code> 判断可用性。例如 <code>inject</code> 目前支持 <code>[skip, drop, modify]</code>；<code>abort</code> 虽在脚本层定义了语义，但尚未被任何 runtime 支持，使用它会直接报错。</li></ul><h2 id="组件与进程" tabindex="-1">组件与进程 <a class="header-anchor" href="#组件与进程" aria-label="Permalink to &quot;组件与进程&quot;">​</a></h2><p>一次 <code>catter &lt;脚本&gt; -- &lt;构建命令&gt;</code> 会涉及多个进程与组件，它们都属于 runtime 的实现，脚本作者通常无需关心：</p><table tabindex="0"><thead><tr><th>组件</th><th>角色</th></tr></thead><tbody><tr><td><code>catter</code>（守护进程）</td><td>加载并运行脚本，持有 JS 运行时，通过 IPC 接收命令并返回决策</td></tr><tr><td><code>catter-proxy</code></td><td>命令执行与 IPC 中转的可执行文件，分注入模式（启动构建）与包装模式（代替被拦截的命令）</td></tr><tr><td>hook 共享库</td><td>inject runtime 的捕获载体，注入构建进程以拦截进程创建调用</td></tr></tbody></table><blockquote><p>早期文档把上述三个组件描述为 catter 的&quot;三层架构&quot;。现在的视角更高一层：它们是 <strong>inject runtime 的实现细节</strong>，而 runtime 抽象本身才是架构的中心。详见<a href="./runtime">运行机制</a>与<a href="./hook-mechanism">钩子机制</a>。</p></blockquote><h2 id="js-运行时模型" tabindex="-1">JS 运行时模型 <a class="header-anchor" href="#js-运行时模型" aria-label="Permalink to &quot;JS 运行时模型&quot;">​</a></h2><p>JS 运行时是单线程的，脚本回调不会并行执行。守护进程的 I/O（IPC 连接、命令收发）是异步并发的，但脚本执行始终串行；依赖全局状态的脚本应留意异步回调可能在 <code>await</code> 处交错。</p>',21))])}const b=r(E,[["render",h]]);export{f as __pageData,b as default};
